  "Du får en bricka och sätter dig vid ett ledigt bord. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Recebes um tabuleiro e sentas-te numa mesa livre. A saciedade e a energia chegam enquanto comes – só quando estás sentado!",
  "Du får maten på en bricka och sätter dig vid ett bord eller i fönstret med utsikt över havet. Mättnaden och energin kommer medan du äter – och när allt är uppätet blir du gladare!": "Recebes a comida num tabuleiro e sentas-te a uma mesa ou à janela com vista para o mar. A saciedade e a energia chegam enquanto comes – e quando acabares tudo ficas mais contente!",
  "Du får maten på en bricka och sätter dig vid ett ledigt bord eller vid fönstret. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Recebes a comida num tabuleiro e sentas-te numa mesa livre ou à janela. A saciedade e a energia chegam enquanto comes – mas só quando estás sentado!",
